-- Produtos Hidramais enviados pelo Daniel (preço a definir na reunião com o contador).
-- Preço R$ 0,00 => cadastrados INATIVOS (o sistema só ativa produto com preço). Impostos em branco.

INSERT INTO "brands" ("id", "name", "active", "sortOrder", "createdAt", "updatedAt")
VALUES (gen_random_uuid(), 'Hidramais', true, 10, now(), now())
ON CONFLICT ("name") DO NOTHING;

-- Loção Desodorante Colágeno e Vitamina E 500ml
INSERT INTO "products" ("id", "sku", "name", "brandId", "description", "unit", "costCents", "taxRefBps", "priceCents",
                        "stockQty", "reservedQty", "active", "internalNotes", "createdAt", "updatedAt")
SELECT gen_random_uuid(), 'HID-COLAGENO-500', 'Loção Desodorante Colágeno e Vitamina E 500ml', b."id", 'Hidratação e Firmeza', 'UN', 0, 0, 0, 0, 0, false,
       'Preço a definir (reunião com o contador). Informe o preço de venda para ativar.', now(), now()
  FROM "brands" b WHERE b."name" = 'Hidramais'
ON CONFLICT ("sku") DO NOTHING;
INSERT INTO "stored_files" ("id", "area", "fileName", "mimeType", "sizeBytes", "data", "createdAt")
SELECT gen_random_uuid(), 'products', 'hid-colageno-vitamina-e-500.webp', 'image/webp', 22518, decode('', 'hex'), now()
WHERE NOT EXISTS (SELECT 1 FROM "stored_files" WHERE "fileName" = 'hid-colageno-vitamina-e-500.webp');
INSERT INTO "product_images" ("id", "productId", "fileName", "mimeType", "isPrimary", "sortOrder", "createdAt")
SELECT gen_random_uuid(), p."id", 'hid-colageno-vitamina-e-500.webp', 'image/webp', true, 0, now()
  FROM "products" p
 WHERE p."sku" = 'HID-COLAGENO-500' AND NOT EXISTS (SELECT 1 FROM "product_images" i WHERE i."productId" = p."id");

